"""Generate exhaustive audit findings from the real catalogue; no DCC invocation."""
import json
from collections import Counter
from pathlib import Path
from catalogue import species_keys

HERE = Path(__file__).resolve().parent


def cell(value):
    return str(value).replace('|', '/').replace('\n', ' / ').replace('\r', '')


def main():
    data = json.loads((HERE / 'catalogue.json').read_text(encoding='utf-8'))
    lines = ['# Flora audit: generated complete findings (#189)', '',
             'Generated by `experiments/flora-library-audit/report_findings.py`. No botanical identity is approved.',
             'Hnnn heights below assume cm, unverified. Export paths are relative to `C:/x/t_366e8d9d`.', '',
             '## Accounting', '', '| Source | Text | Paired | Ambiguous | Orphan/note | Headings | Plant meshes | Normalized captions | NPM candidates | VPM candidates |',
             '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for scene in data['scenes']:
        c = Counter(l['status'] for l in scene['labels'])
        entries = scene['entries']
        names = set().union(*(species_keys(e) for e in entries))
        lines.append('| ' + ' | '.join(map(str, [scene['source']['scene'], len(scene['labels']), c['paired'], c['ambiguous'], c['unpaired'], c['category_heading'], len(entries), len(names), sum('NPM' in e['profile_candidates'] for e in entries), sum('VPM' in e['profile_candidates'] for e in entries)])) + ' |')
    lines += ['', 'Headings count as explicit orphan/non-asset records for Text = paired + ambiguous + orphan accounting.',
              'Normalized captions include cultivar-only strings and multiline alternatives; this is not a curated species count.', '',
              '## Every ambiguous or unpaired label', '', '| Source | Label name / handle | Raw text | Status / reason | Candidate entry IDs |', '|---|---|---|---|---|']
    for index, scene in enumerate(data['scenes']):
        ids = {e['source_handle']:e['id'] for e in scene['entries']}
        for l in scene['labels']:
            if l['status'] != 'paired':
                values = [index, f"{l['name']} / {l['handle']}", l['text'], l['status'] + ': ' + ', '.join(l['ambiguity_reasons']), ', '.join(ids[h] for h in l['candidate_handles'])]
                lines.append('| ' + ' | '.join(cell(v) for v in values) + ' |')
    lines += ['', 'Source 0 = library, source 1 = FLORIO project. Candidate source names and complete per-label bbox/positions are in catalogue JSON.', '',
              '## Every plant mesh without a species label', '', '| Entry ID | Source name | Triangles | Bbox XYZ metres |', '|---|---|---:|---|']
    for scene in data['scenes']:
        for e in scene['entries']:
            if not e['species_labels']:
                lines.append('| ' + ' | '.join(cell(v) for v in [e['id'], e['source_name'], e['triangles'], [round(x,6) for x in e['dimensions_m']]]) + ' |')
    lines += ['', '## Excluded nonplant meshes (all names; not silently treated as paired)', '',
              '| Source | Name | Audit role | Triangles | Material |', '|---|---|---|---:|---|']
    for index, scene in enumerate(data['scenes']):
        for node in scene['excluded_nodes']:
            if node['triangles']:
                lines.append('| ' + ' | '.join(cell(v) for v in [index, node['name'], node['role'], node['triangles'], node['material_name']]) + ' |')
    lines += ['', '## Labelled-height vs measured-height differences above 10%', '',
              'Each H-token comparison is shown, including alternatives in a multiline schedule; not all alternatives belong to this mesh.', '',
              '| Entry ID | Source name | Measured height m | Label H heights m if cm | Deviations % if cm | Node-name deviation mm |', '|---|---|---:|---|---|---:|']
    for scene in data['scenes']:
        for e in scene['entries']:
            dims = e['labelled_dimensions']
            deviations = dims['schedule_height_deviations_pct_if_cm']
            if any(abs(d) > 10 for d in deviations) or 'measured_height_outside_10pct_of_node_token' in e['findings']:
                values = [e['id'], e['source_name'], round(e['dimensions_m'][2],6), dims['raw_height_tokens_m_if_cm'], [round(d,3) for d in deviations], dims['height_deviation_from_name_mm']]
                lines.append('| ' + ' | '.join(cell(v) for v in values) + ' |')
    lines += ['', '## Descriptive library budgets (not regulatory limits)', '', '| Type | Profile | n | Min | Median | p90 nearest-rank | Max | Review above |', '|---|---|---:|---:|---:|---:|---:|---:|']
    for b in data['proposed_budgets']:
        if b['profile'] != 'unknown' and b['type'] in ('tree','bush','hedge'):
            lines.append('| ' + ' | '.join(str(b[k]) for k in ['type','profile','n','min','median','p90','max','proposed_review_above']) + ' |')
    lines += ['', 'Profile candidates overlap for LP -> HP. Budget = observed ceiling rounded up to 100; p90 shown separately, not imposed as a limit.', '',
              '## Library versus project species-caption comparison', '']
    comparison = data['project_vs_library']
    for key in ['shared_species_names', 'library_only_species_names', 'project_only_species_names']:
        lines += [f"### {key} ({len(comparison[key])})", ''] + ['- ' + s for s in comparison[key]] + ['']
    lines += ['Exact normalized captions only; spelling/cultivar differences are not repaired. Geometry-only candidates are not species identity.', '',
              '| Project entry | Library name candidates | Exact-triangle / bbox within 20% candidates |', '|---|---|---|']
    for row in comparison['entries']:
        lines.append('| ' + ' | '.join(cell(v) for v in [row['project_id'], row['library_name_candidates'], row['dimension_and_triangle_candidates']]) + ' |')
    target = HERE.parents[1] / 'docs/experiments/flora-library-audit-findings.md'
    target.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print('Generated', target, len(lines), 'lines')


if __name__ == '__main__':
    main()
